def txi_js():
    if C.L == "en":
        return """var TXI = {
  grupo: "Group",
  igual: function (h) { return "<strong>The two groups are the same,</strong> so both reach " + h.toFixed(1) + " cm after six weeks. This is your starting point. Now change <strong>one</strong> factor in group B and run the trial again."; },
  uno: function (f, a, b, d) { return "<strong>Only the " + f + " changed.</strong> Group A: " + a.toFixed(1) + " cm. Group B: " + b.toFixed(1) + " cm. Everything else was the same, so the difference of " + d.toFixed(1) + " cm can only come from the " + f + ". <strong>You can draw a conclusion from this trial.</strong> Group A is your control group."; },
  varios: function (fs, a, b) { return "<strong>You changed " + fs.length + " factors at once (" + fs.join(", ") + ").</strong> Group A: " + a.toFixed(1) + " cm. Group B: " + b.toFixed(1) + " cm. Which factor caused the difference? It could be one, the other, all of them together, or one could push one way and another the opposite way. <strong>Nothing can be concluded.</strong> Go back and change only one factor."; }
};"""
    return """var TXI = {
  grupo: "Grupo",
  igual: function (h) { return "<strong>Los dos grupos son iguales,</strong> así que ambos llegan a " + h.toFixed(1) + " cm a las seis semanas. Ese es su punto de partida. Ahora cambie <strong>un</strong> factor en el grupo B y repita el ensayo."; },
  uno: function (f, a, b, d) { return "<strong>Solo cambió: " + f + ".</strong> Grupo A: " + a.toFixed(1) + " cm. Grupo B: " + b.toFixed(1) + " cm. Todo lo demás fue igual, así que la diferencia de " + d.toFixed(1) + " cm solo puede deberse a ese factor. <strong>De este ensayo se puede sacar una conclusión.</strong> El grupo A es su grupo de control."; },
  varios: function (fs, a, b) { return "<strong>Cambió " + fs.length + " factores a la vez (" + fs.join(", ") + ").</strong> Grupo A: " + a.toFixed(1) + " cm. Grupo B: " + b.toFixed(1) + " cm. ¿Cuál causó la diferencia? Pudo ser uno, el otro, todos juntos, o que uno empujara en un sentido y otro en el contrario. <strong>No se puede concluir nada.</strong> Vuelva atrás y cambie un solo factor."; }
};"""


