         (t("What each tube has", "Condiciones de los tubos"), [t("Tube", "Tubo"), t("Extra content", "Contenido adicional")], [["1", t("Nothing (only H₂O₂)", "Nada (solo H₂O₂)")], ["2", t("A small strip of platinum", "Laminilla de platino")], ["3", t("A strip of platinum + stirring", "Laminilla de platino + agitación")]]),
